		, ends.length === 0 ? undefined : Math.min(...ends));
	assert.match(body, /^ {4}if: inputs\.suite == 'produce'$/mu);
	assert.ok(body.includes(`uses: ./.github/workflows/${workflow}.yml`));
	assert.ok(body.includes("host_null: true"));
}
